#include <format>
#include <iostream>
#include <stdexcept>
#include <string>
#include <utility>
#include <vector>

struct Part {
  explicit Part(std::string part_name) : name(std::move(part_name)) {}
  Part(const Part& other) : name(other.name) {
    if (name == "cracked housing") throw std::runtime_error("cannot copy the cracked housing");
  }
  Part(Part&& other) : name(std::move(other.name)) {}  // not noexcept, so the vector copies instead
  Part& operator=(const Part&) = default;
  Part& operator=(Part&&) = default;
  ~Part() = default;

  std::string name;
};

int main() {
  std::vector<Part> parts;
  parts.reserve(2);
  parts.emplace_back("wheel");
  parts.emplace_back("cracked housing");
  try {
    parts.push_back(Part("motor"));  // full: needs new storage for all three parts
  } catch (const std::runtime_error& e) {
    std::cout << std::format("push_back failed: {}\n", e.what());
  }
  std::cout << std::format("size {}, capacity {}:", parts.size(), parts.capacity());
  for (const Part& part : parts) std::cout << std::format(" [{}]", part.name);
  std::cout << '\n';
}

