#include <stdexcept>
#include <string>
#include <string_view>
#include <vector>

class Route {
 public:
  // Appends each name in turn, and throws at a blank one.
  void append(std::span<const std::string_view> names) {
    for (const std::string_view name : names) {
      if (name.empty()) throw std::invalid_argument("blank waypoint name");
      waypoints_.emplace_back(name);
    }
  }
  [[nodiscard]] std::string describe() const {
    std::string text;
    for (const std::string& waypoint : waypoints_) text += (text.empty() ? "" : ", ") + waypoint;
    return text;
  }

 private:
  std::vector<std::string> waypoints_;
};

int main() {
  Route route;
  constexpr std::array<std::string_view, 1> start{"dock"};
  route.append(start);
  constexpr std::array<std::string_view, 3> batch{"shelf", "", "gate"};
  try {
    route.append(batch);
  } catch (const std::invalid_argument& e) {
    std::cout << std::format("append failed: {}\n", e.what());
  }
  std::cout << std::format("route: {}\n", route.describe());
}

#include <array>
