#include <unordered_map>
#include <vector>

using Index = std::unordered_map<std::string, std::ptrdiff_t>;

// Adds one name to an index, and refuses a name that is already there.
void index_name(Index& index, std::string_view name, std::ptrdiff_t position) {
  if (!index.try_emplace(std::string(name), position).second) {
    throw std::invalid_argument(std::format("duplicate waypoint {}", name));
  }
}

// Invariant: index_ maps every name in order_ to its position there, and holds nothing else.
class Mission {
 public:
  // No guarantee: a duplicate throws between the two updates, and the invariant breaks.
  void add_all_unsafe(std::span<const std::string_view> names) {
    for (const std::string_view name : names) {
      order_.emplace_back(name);
      index_name(index_, name, std::ssize(order_) - 1);
    }
  }

  // Strong guarantee: everything that can throw works on copies, and the commit can't throw.
  void add_all(std::span<const std::string_view> names) {
    std::vector<std::string> order = order_;
    Index index = index_;
    for (const std::string_view name : names) {
      order.emplace_back(name);
      index_name(index, name, std::ssize(order) - 1);
    }
    order_.swap(order);  // noexcept
    index_.swap(index);  // noexcept
  }

  [[nodiscard]] std::string summary() const {
    return std::format("{} in order, {} in the index", order_.size(), index_.size());
  }

 private:
  std::vector<std::string> order_;
  Index index_;
};

int main() {
  constexpr std::array<std::string_view, 2> start{"dock", "shelf"};
  constexpr std::array<std::string_view, 3> batch{"gate", "dock", "charger"};

  Mission unsafe;
  unsafe.add_all_unsafe(start);
  try {
    unsafe.add_all_unsafe(batch);
  } catch (const std::invalid_argument& e) {
    std::cout << std::format("unsafe: {}; now {}\n", e.what(), unsafe.summary());
  }

  Mission strong;
  strong.add_all(start);
  try {
    strong.add_all(batch);
  } catch (const std::invalid_argument& e) {
    std::cout << std::format("strong: {}; still {}\n", e.what(), strong.summary());
  }
}

