#include <optional>
#include <span>
#include <stdexcept>
#include <string>
#include <string_view>
#include <system_error>

struct Entry {
  std::string_view name;
  double value = 0;
};

// Parses "name=value", or throws std::invalid_argument naming the line.
[[nodiscard]] Entry parse_line(std::string_view line, std::ptrdiff_t number) {
  const auto equals = line.find('=');
  if (equals == std::string_view::npos || equals == 0) {
    throw std::invalid_argument(std::format("line {}: expected name=value", number));
  }
  const std::string_view text = line.substr(equals + 1);
  double value = 0;
  const auto [end, error] = std::from_chars(text.data(), text.data() + text.size(), value);
  if (error != std::errc{} || end != text.data() + text.size()) {
    throw std::invalid_argument(std::format("line {}: {} is not a number", number, text));
  }
  return {.name = line.substr(0, equals), .value = value};
}

class ParameterStore {
 public:
  // Strong guarantee: applies every line, or throws and changes nothing.
  void apply(std::span<const std::string_view> lines) {
    const std::scoped_lock lock(mutex_);
    std::map<std::string, double, std::less<>> staged = values_;
    for (std::ptrdiff_t i = 0; i < std::ssize(lines); ++i) {
      const Entry entry = parse_line(lines[i], i + 1);
      staged.insert_or_assign(std::string(entry.name), entry.value);
    }
    values_.swap(staged);  // the commit: noexcept
  }

  [[nodiscard]] std::optional<double> get(std::string_view name) const {
    const std::scoped_lock lock(mutex_);
    const auto found = values_.find(name);
    if (found == values_.end()) return std::nullopt;
    return found->second;
  }

 private:
  mutable std::mutex mutex_;
  std::map<std::string, double, std::less<>> values_;
};

int main() {
  ParameterStore store;
  const auto try_apply = [&store](std::span<const std::string_view> lines) {
    try {
      store.apply(lines);
      std::cout << "applied\n";
    } catch (const std::invalid_argument& e) {
      std::cout << std::format("refused, {}\n", e.what());
    }
  };
  const auto show = [&store] {
    std::cout << std::format("max_speed {}, wheel_base {}, accel {}\n", store.get("max_speed").value(),
                             store.get("wheel_base").value(), store.get("accel") ? "set" : "not set");
  };

  constexpr std::array<std::string_view, 2> initial{"max_speed=1.5", "wheel_base=0.35"};
  constexpr std::array<std::string_view, 3> missing_equals{"accel=0.8", "max_speed", "wheel_base=0.4"};
  constexpr std::array<std::string_view, 1> not_a_number{"max_speed=fast"};
  constexpr std::array<std::string_view, 1> update{"max_speed=2.0"};

  try_apply(initial);
  try_apply(missing_equals);
  try_apply(not_a_number);
  show();
  try_apply(update);
  show();
}

