struct NothrowMove {
  NothrowMove() = default;
  NothrowMove(const NothrowMove&) { std::cout << "copy\n"; }
  NothrowMove(NothrowMove&&) noexcept { std::cout << "move\n"; }
  NothrowMove& operator=(const NothrowMove&) = default;
  NothrowMove& operator=(NothrowMove&&) = default;
  ~NothrowMove() = default;
};

struct ThrowingMove {
  ThrowingMove() = default;
  ThrowingMove(const ThrowingMove&) { std::cout << "copy\n"; }
  ThrowingMove(ThrowingMove&&) { std::cout << "move\n"; }
  ThrowingMove& operator=(const ThrowingMove&) = default;
  ThrowingMove& operator=(ThrowingMove&&) = default;
  ~ThrowingMove() = default;
};

struct MoveOnly {
  MoveOnly() = default;
  MoveOnly(const MoveOnly&) = delete;
  MoveOnly(MoveOnly&&) { std::cout << "move\n"; }
  MoveOnly& operator=(const MoveOnly&) = delete;
  MoveOnly& operator=(MoveOnly&&) = default;
  ~MoveOnly() = default;
};

template <typename T>
void relocate(std::string_view label) {
  T original;
  std::cout << std::format("{:<14} nothrow move {:<5} relocated by ", label,
                           std::is_nothrow_move_constructible_v<T>);
  const T relocated(std::move_if_noexcept(original));
}

int main() {
  relocate<NothrowMove>("NothrowMove");
  relocate<ThrowingMove>("ThrowingMove");
  relocate<MoveOnly>("MoveOnly");
}

