[[nodiscard]] double checked_speed(double metres_per_second) noexcept {
  if (metres_per_second > 2.0) throw std::out_of_range("speed above the limit");
  return metres_per_second;
}

int main() { return checked_speed(1.0) > 0.0 ? 0 : 1; }

[[nodiscard]] double parse_speed(std::string_view text);  // throws std::invalid_argument("not a speed")

[[nodiscard]] double speed_or_zero(std::string_view text) noexcept { return parse_speed(text); }

int main() {
  try {
    std::cout << speed_or_zero("1.5") << '\n';
    std::cout << speed_or_zero("fast") << '\n';
  } catch (const std::invalid_argument& e) {
    std::cout << "caught: " << e.what() << '\n';  // never reached
  }
}

class Transaction {
 public:
  ~Transaction() noexcept(false) {
    if (!committed_) throw std::runtime_error("rollback failed");
  }
  void commit() { committed_ = true; }

 private:
  bool committed_ = false;
};

void save() {
  const Transaction transaction;
  throw std::runtime_error("disk full");  // unwinding destroys transaction, which throws again
}

#include <deque>
#include <format>
#include <iostream>
#include <string_view>
#include <type_traits>
#include <vector>

struct Counts {
  int copies = 0;
  int moves = 0;
};

// Counts how the object that holds it is relocated.
class Probe {
 public:
  explicit Probe(Counts& counts) : counts_(&counts) {}
  Probe(const Probe& other) : counts_(other.counts_) { ++counts_->copies; }
  Probe(Probe&& other) noexcept : counts_(other.counts_) { ++counts_->moves; }
  Probe& operator=(const Probe&) = default;
  Probe& operator=(Probe&&) = default;
  ~Probe() = default;

 private:
  Counts* counts_;
};

struct Pose {
  double x = 0;
  double y = 0;
};

template <typename History>
struct Track {
  History history;
  Probe probe;
};

template <typename History>
void grow(std::string_view label) {
  Counts counts;
  std::vector<Track<History>> tracks;
  tracks.reserve(4);
  for (int i = 0; i < 4; ++i) tracks.push_back(Track<History>{.history = History(100), .probe = Probe(counts)});
  counts = Counts{};
  tracks.reserve(8);  // relocates the four tracks
  std::cout << std::format("{:<12} nothrow move {:<5} relocation: {} copies, {} moves\n", label,
                           std::is_nothrow_move_constructible_v<Track<History>>, counts.copies, counts.moves);
}

int main() {
  grow<std::vector<Pose>>("std::vector");
  grow<std::deque<Pose>>("std::deque");
}
